import{_ as o,o as e,c as t,ak as i}from"./chunks/framework.DDz3O3n6.js";const b=JSON.parse('{"title":"什么是 Godot Engine","description":"","frontmatter":{"title":"什么是 Godot Engine","index":0},"headers":[],"relativePath":"godot/godot-4-what-is-engine.md","filePath":"godot/godot-4-what-is-engine.md","lastUpdated":1780628909000}'),r={name:"godot/godot-4-what-is-engine.md"};function d(l,a,n,h,s,p){return e(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="什么是-godot-engine" tabindex="-1">什么是 Godot Engine？ <a class="header-anchor" href="#什么是-godot-engine" aria-label="Permalink to “什么是 Godot Engine？”">​</a></h1><p>Godot 是一款<strong>免费、开源、轻量</strong>的游戏引擎。<br> 它可以用来做 <strong>2D、3D、UI、工具程序</strong>，甚至还能做一些很有意思的小型交互应用。</p><p>如果你想快速做出一个可玩的游戏原型，Godot 是一个很舒服的选择。<br> 它不像一些大型引擎那样一上来就很重，打开后你会发现：界面清爽，学习路径也比较直接。</p><h2 id="它适合做什么" tabindex="-1">它适合做什么？ <a class="header-anchor" href="#它适合做什么" aria-label="Permalink to “它适合做什么？”">​</a></h2><p>Godot 很适合这些场景：</p><ul><li>2D 横版游戏</li><li>像素风游戏</li><li>独立小游戏</li><li>关卡编辑器</li><li>游戏原型验证</li></ul><p>如果你喜欢“写一点代码，马上看到结果”，Godot 会让你比较有成就感。</p><h2 id="godot-的几个特点" tabindex="-1">Godot 的几个特点 <a class="header-anchor" href="#godot-的几个特点" aria-label="Permalink to “Godot 的几个特点”">​</a></h2><h3 id="_1-免费开源" tabindex="-1">1. 免费开源 <a class="header-anchor" href="#_1-免费开源" aria-label="Permalink to “1. 免费开源”">​</a></h3><p>Godot 不收授权费，也没有商业门槛。<br> 你可以直接下载、学习、发布作品。</p><h3 id="_2-轻量" tabindex="-1">2. 轻量 <a class="header-anchor" href="#_2-轻量" aria-label="Permalink to “2. 轻量”">​</a></h3><p>它体积小，启动快，对新手很友好。<br> 不需要先和一堆复杂设置打交道。</p><h3 id="_3-节点式结构" tabindex="-1">3. 节点式结构 <a class="header-anchor" href="#_3-节点式结构" aria-label="Permalink to “3. 节点式结构”">​</a></h3><p>Godot 的核心思路是“节点 + 场景”。<br> 刚开始可能有点陌生，但一旦理解了，你会发现它很像搭积木：<br> 角色、摄像机、UI、动画，都是一个个节点拼出来的。</p><h3 id="_4-自带-gdscript" tabindex="-1">4. 自带 GDScript <a class="header-anchor" href="#_4-自带-gdscript" aria-label="Permalink to “4. 自带 GDScript”">​</a></h3><p>Godot 的脚本语言 GDScript 很像 Python，语法简单，适合快速开发。<br> 新手通常能比较快上手。</p><h2 id="为什么很多人喜欢它" tabindex="-1">为什么很多人喜欢它？ <a class="header-anchor" href="#为什么很多人喜欢它" aria-label="Permalink to “为什么很多人喜欢它？”">​</a></h2><p>因为它不像“工具”，更像“创作台”。<br> 你不需要先学一大堆复杂流程，很多时候可以直接开始做东西。</p><p>对于独立开发者来说，这点很重要。<br> 少一点阻力，就能多一点创作。</p><h2 id="一句话理解-godot" tabindex="-1">一句话理解 Godot <a class="header-anchor" href="#一句话理解-godot" aria-label="Permalink to “一句话理解 Godot”">​</a></h2><p>你可以把 Godot 理解成：</p><blockquote><p>一个专门帮你把游戏想法快速变成可运行作品的引擎。</p></blockquote><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to “下一步”">​</a></h2><p>接下来，你可以继续学习：</p><ul><li>Godot 4 和 Godot 3 的区别</li><li>如何安装 Godot</li><li>编辑器界面怎么用</li><li>第一个 Hello World 场景怎么做</li></ul><p>如果你已经准备好了，我们就从下一篇开始正式进入 Godot 4。</p>',26)])])}const g=o(r,[["render",d]]);export{b as __pageData,g as default};
